function getRoomCode() {
  const code = "EXBVHN";
  const url = new URL(location.href);
  const requested = (url.searchParams.get("room") || "").toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 12);
  if (!K8_PROD && requested && requested !== code) return requested;
  if (url.searchParams.get("room") !== code) {
    url.searchParams.set("room", code);
    history.replaceState({}, "", url);
  }
  return code;
}

const api = cloudMode ? createCloudApi() : createLocalApi();

function nullIfEmpty(value){return value||null}

function createCloudApi() {
  async function rpc(name, payload = {}, timeoutMs = 20000) {
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);
    try{
      const response = await fetch(`${cfg.SUPABASE_URL}/rest/v1/rpc/${name}`, {
        method: "POST",
        headers: {
          apikey: cfg.SUPABASE_ANON_KEY,
          Authorization: `Bearer ${cfg.SUPABASE_ANON_KEY}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify(payload),
        signal:controller.signal
      });
      if (!response.ok) {
        const data = await response.json().catch(() => ({}));
        throw new Error(data.message || data.hint || `Ошибка сервера: ${response.status}`);
      }
      return response.status === 204 ? null : response.json();
    }catch(error){
      if(error?.name==="AbortError")throw new Error("Сервер слишком долго отвечает");
      throw error;
    }finally{clearTimeout(timer)}
  }
  async function pagedHistoryFallback(){
    let cursor=null,hasMore=true,summaries=[],guard=0;
    while(hasMore&&guard++<20){
      const page=await rpc("korova_archive_search_v3",{p_code:roomCode,p_cursor:cursor,p_limit:50,p_query:null,p_from:null,p_to:null,p_participant:null,p_winner:null,p_player_count:null,p_score_mode:null});
      summaries.push(...(page?.items||[]));cursor=page?.nextCursor||null;hasMore=!!page?.hasMore&&!!cursor;
      historyProgress=`Найдено ${summaries.length} партий…`;if(tab==="stats")render();
    }
    const games=[];
    for(let i=0;i<summaries.length;i+=8){
      const chunk=await Promise.all(summaries.slice(i,i+8).map(item=>rpc("korova_game_detail",{p_code:roomCode,p_game_id:item.id})));
      games.push(...chunk.filter(Boolean));historyProgress=`Загружено ${games.length} из ${summaries.length} партий`;if(tab==="stats")render();
    }
    return games.sort((a,b)=>new Date(b.finishedAt||b.startedAt)-new Date(a.finishedAt||a.startedAt));
  }
  return {
    adminLogin: (pin) => rpc("korova_admin_login",{p_code:roomCode,p_pin:pin}),
    getProfileExtras: () => rpc("korova_get_profile_extras",{p_code:roomCode},10000),
    setProfileExtras: async (profileId,x) => { try { const rows=await rpc("korova_set_profile_extras_v2",{p_code:roomCode,p_profile_id:profileId,p_frame:x.frame,p_battle_cry:x.battleCry,p_lucky_card:x.luckyCard,p_pattern:x.pattern,p_accent:x.accent}); k8ExtrasV2=true; return rows; } catch(e) { if(!/extras_v2|schema cache|404|function/i.test(e.message||"")) throw e; k8ExtrasV2=false; return rpc("korova_set_profile_extras",{p_code:roomCode,p_profile_id:profileId,p_frame:x.frame,p_battle_cry:x.battleCry}); } },
    updateProfile: (profileId,name,emoji,accent,pattern,featuredAward) => rpc("korova_update_profile_identity",{p_code:roomCode,p_profile_id:profileId,p_name:name,p_emoji:emoji,p_accent:accent,p_pattern:pattern,p_featured_award:featuredAward||null}),
    deleteGame:gameId=>rpc("korova_admin_delete_game_safe",{p_code:roomCode,p_token:adminToken(),p_game_id:gameId}),
    mergeProfiles: (source,target) => rpc("korova_admin_merge_profiles",{p_code:roomCode,p_token:adminToken(),p_source:source,p_target:target}),
    ensure: () => rpc("korova_ensure_room", { p_code: roomCode }),
    getState: async () => { const s=await rpc("korova_get_state",{p_code:roomCode});s.currentGame.draftScores=await rpc("korova_get_draft_scores",{p_code:roomCode});return s; },
    getLiveState: () => rpc("korova_live_state",{p_code:roomCode}),
    getHistory: async()=>{try{const data=await rpc("korova_history_data",{p_code:roomCode},12000);if(Array.isArray(data))return data;if(Array.isArray(data?.archive))return data.archive}catch{}try{const legacy=await rpc("korova_get_state",{p_code:roomCode},12000);if(Array.isArray(legacy?.archive))return legacy.archive}catch{}return pagedHistoryFallback()},
    archivePage:(cursor=null,limit=12,filters={})=>rpc("korova_archive_search_v3",{p_code:roomCode,p_cursor:cursor,p_limit:limit,p_query:filters.query||null,p_from:filters.from||null,p_to:filters.to||null,p_participant:nullIfEmpty(filters.participant),p_winner:nullIfEmpty(filters.winner),p_player_count:filters.playerCount?Number(filters.playerCount):null,p_score_mode:filters.mode||null}),
    gameDetail: gameId=>rpc("korova_game_detail",{p_code:roomCode,p_game_id:gameId}),
    addPlayer: (name,emoji)=>rpc("korova_add_player",{p_code:roomCode,p_name:name,p_emoji:emoji}),
    removePlayer: playerId=>rpc("korova_remove_player",{p_code:roomCode,p_player_id:playerId}),
    addExistingPlayer: profileId=>rpc("korova_add_existing_player",{p_code:roomCode,p_profile_id:profileId}),
    updatePlayerIcon: (playerId,emoji)=>rpc("korova_update_player_icon",{p_code:roomCode,p_player_id:playerId,p_emoji:emoji}),
    addRound: (scores) => rpc("korova_add_round", { p_code: roomCode, p_scores: scores }),
    setDraftScore: (playerId, score) => rpc("korova_set_draft_score", { p_code: roomCode, p_player_id: playerId, p_score: score }),
    clearDraftScore: (playerId) => rpc("korova_clear_draft_score", { p_code: roomCode, p_player_id: playerId }),
    finalizeRound: async token=>{try{return await rpc("korova_finalize_round_v2",{p_code:roomCode,p_client_token:token})}catch(e){if(/finalize_round_v2|schema cache|404/i.test(e.message))return rpc("korova_finalize_round",{p_code:roomCode});throw e}},
    importGame: async(playedAt,profiles,rounds,mode)=>{try{return await rpc("korova_import_game_v2",{p_code:roomCode,p_played_at:playedAt,p_profiles:profiles,p_rounds:rounds,p_score_mode:mode})}catch(e){if(mode==="rounds"&&/import_game_v2|schema cache|404/i.test(e.message))return rpc("korova_import_game",{p_code:roomCode,p_played_at:playedAt,p_profiles:profiles,p_rounds:rounds});throw e}},
    setGameScoreMode:(gameId,mode)=>rpc("korova_admin_set_game_score_mode_safe",{p_code:roomCode,p_token:adminToken(),p_game_id:gameId,p_score_mode:mode}),
    updateArchivedGame:(gameId,rounds,playedAt)=>rpc("korova_admin_update_archived_game_v3",{p_code:roomCode,p_token:adminToken(),p_game_id:gameId,p_rounds:rounds,p_played_at:playedAt}),
    auditLog:(limit=100)=>rpc("korova_admin_audit_log_v2",{p_code:roomCode,p_token:adminToken(),p_limit:limit}),
    systemVersion:()=>rpc("korova_system_version",{}),
    undoAudit:auditId=>rpc("korova_admin_undo_audit",{p_code:roomCode,p_token:adminToken(),p_audit_id:auditId}),
    updateRound: (roundId,scores)=>rpc("korova_update_round",{p_code:roomCode,p_round_id:roundId,p_scores:scores}),
    undoRound: ()=>rpc("korova_undo_last_round",{p_code:roomCode}),
    newGame: keepPlayers=>rpc("korova_new_game",{p_code:roomCode,p_keep_players:keepPlayers})
  };
}

function createLocalApi() {
  const key = `korova-room-${roomCode}`;
  const uid = () => crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;
  function fresh() {
    return {
      room: { code: roomCode, createdAt: new Date().toISOString() },
      knownPlayers: [],
      currentGame: { id: uid(), startedAt: new Date().toISOString(), players: [], rounds: [], draftScores: {} },
      archive: []
    };
  }
  function load() {
    try {
      const s = JSON.parse(localStorage.getItem(key)) || fresh();
      if (!Array.isArray(s.knownPlayers)) s.knownPlayers = [];
      if (!s.currentGame.draftScores) s.currentGame.draftScores = {};
      const allPlayers = [...(s.currentGame?.players || []), ...(s.archive || []).flatMap(g => g.players || [])];
      for (const player of allPlayers) {
        let profile = s.knownPlayers.find(x => x.id === player.profileId) || s.knownPlayers.find(x => x.name.trim().toLowerCase() === player.name.trim().toLowerCase());
        if (!profile) { profile = { id: uid(), name: player.name, emoji: player.emoji }; s.knownPlayers.push(profile); }
        player.profileId = profile.id;
      }
      localStorage.setItem(key, JSON.stringify(s));
      return s;
    } catch { return fresh(); }
  }
  function save(value) { localStorage.setItem(key, JSON.stringify(value)); return structuredClone(value); }
  const auditKey=`${key}-audit`;
  function audits(){try{return JSON.parse(localStorage.getItem(auditKey)||"[]")}catch{return[]}}
  function recordAudit(action,summary,beforeState,entityId=null){const rows=audits();rows.unshift({id:uid(),action,summary,entityId,createdAt:new Date().toISOString(),undoneAt:null,undoable:true,beforeState});localStorage.setItem(auditKey,JSON.stringify(rows.slice(0,50)))}
  return {
    adminLogin: async pin => ({token:"local",expiresAt:"2099-01-01T00:00:00Z"}),
    getProfileExtras: async () => { try { return JSON.parse(localStorage.getItem(`${key}-extras`) || "[]"); } catch { return []; } },
    setProfileExtras: async (profileId,x) => { let rows=[]; try { rows=JSON.parse(localStorage.getItem(`${key}-extras`) || "[]"); } catch {} rows=rows.filter(r=>r.id!==profileId); if(x.frame||x.battleCry||x.luckyCard||x.pattern||x.accent) rows.push({id:profileId,frame:x.frame||null,battleCry:x.battleCry||null,luckyCard:x.luckyCard||null,pattern:x.pattern||null,accent:x.accent||null}); localStorage.setItem(`${key}-extras`,JSON.stringify(rows)); return rows; },
    deleteGame:async gameId=>{const before=load(),s=structuredClone(before),game=s.archive.find(g=>g.id===gameId);if(!game)throw new Error("Партия не найдена");s.archive=s.archive.filter(g=>g.id!==gameId);recordAudit("delete_game",`Удалена партия ${new Date(game.finishedAt||game.startedAt).toLocaleDateString("ru-RU")}`,before,gameId);return save(s)},
    mergeProfiles:async(source,target)=>{const before=load(),s=structuredClone(before),from=s.knownPlayers.find(x=>x.id===source),to=s.knownPlayers.find(x=>x.id===target);for(const x of [s.currentGame,...s.archive].flatMap(g=>g.players||[]))if(x.profileId===source)x.profileId=target;s.knownPlayers=s.knownPlayers.filter(x=>x.id!==source);recordAudit("merge_profiles",`Объединены ${from?.name||"профиль"} → ${to?.name||"профиль"}`,before,target);return save(s)},
    setGameScoreMode:async(gameId,mode)=>{const before=load(),s=structuredClone(before),g=s.archive.find(x=>x.id===gameId);if(!g)throw new Error("Партия не найдена");g.scoreMode=mode;recordAudit("score_mode",`Изменён тип архивной партии`,before,gameId);return save(s)},
    updateArchivedGame:async(gameId,rounds,playedAt)=>{const before=load(),s=structuredClone(before),g=s.archive.find(x=>x.id===gameId);if(!g)throw new Error("Партия не найдена");const byId=new Map(g.rounds.map(r=>[r.id,r]));g.rounds=rounds.map((patch,i)=>{const old=patch.roundId?byId.get(patch.roundId):null;return{id:old?.id||uid(),number:i+1,createdAt:old?.createdAt||new Date(new Date(playedAt||g.finishedAt||g.startedAt).getTime()+i*60000).toISOString(),scores:{...patch.scores}}});if(playedAt){const time=(g.finishedAt||g.startedAt||"").slice(11)||"12:00:00.000Z";g.finishedAt=`${playedAt.slice(0,10)}T${time}`}recordAudit("update_game",`Исправлены дата и результаты архивной партии`,before,gameId);save(s);return structuredClone(g)},
    auditLog:async(limit=100)=>audits().slice(0,limit).map(row=>({...row,beforeData:row.beforeState?.archive?.find(g=>g.id===row.entityId)||null,afterData:load().archive.find(g=>g.id===row.entityId)||null,beforeState:undefined})),
    systemVersion:async()=>"7.0.0",
    undoAudit:async auditId=>{const rows=audits(),entry=rows.find(x=>x.id===auditId);if(!entry||entry.undoneAt)throw new Error("Изменение уже отменено или не найдено");save(entry.beforeState);entry.undoneAt=new Date().toISOString();entry.undoable=false;localStorage.setItem(auditKey,JSON.stringify(rows));return load()},
    updateProfile: async (profileId,name,emoji,accent,pattern,featuredAward)=>{const s=load(),pr=s.knownPlayers.find(x=>x.id===profileId);if(pr){Object.assign(pr,{name,emoji,accent,pattern,featuredAward:featuredAward||null})}for(const x of [s.currentGame,...s.archive].flatMap(g=>g.players||[]))if(x.profileId===profileId){x.name=name;x.emoji=emoji}return save(s)},
    ensure: async () => { if (!localStorage.getItem(key)) save(fresh()); },
    getState: async () => structuredClone(load()),
    getLiveState: async()=>{const s=structuredClone(load());s.archiveCount=s.archive.length;return s},
    getHistory: async()=>structuredClone(load().archive),
    archivePage:async(cursor=null,limit=12,filters={})=>{const all=load().archive.map(g=>({g,r:rankingFor(g)})).filter(({g,r})=>{const d=(g.finishedAt||g.startedAt||"").slice(0,10),q=(filters.query||"").trim().toLowerCase();return(!q||g.players.some(p=>p.name.toLowerCase().includes(q)))&&(!filters.from||d>=filters.from)&&(!filters.to||d<=filters.to)&&(!filters.participant||g.players.some(p=>p.profileId===filters.participant))&&(!filters.winner||r[0]?.profileId===filters.winner)&&(!filters.playerCount||g.players.length===Number(filters.playerCount))&&(!filters.mode||(g.scoreMode||"rounds")===filters.mode)}).sort((a,b)=>new Date(b.g.finishedAt)-new Date(a.g.finishedAt));const before=cursor?.finishedAt||cursor,filtered=all.filter(({g})=>!before||new Date(g.finishedAt)<new Date(before)),slice=filtered.slice(0,limit),items=slice.map(({g,r})=>{const w=r[0];return{id:g.id,startedAt:g.startedAt,finishedAt:g.finishedAt,playerCount:g.players.length,roundCount:g.rounds.length,scoreMode:g.scoreMode||"rounds",winner:w?{profileId:w.profileId,name:w.name,emoji:w.emoji,total:w.total}:null}}),wins=new Map();for(const {r} of all){const w=r[0];if(w){const x=wins.get(w.profileId)||{profileId:w.profileId,name:w.name,emoji:w.emoji,wins:0};x.wins++;wins.set(w.profileId,x)}}const topWinner=[...wins.values()].sort((a,b)=>b.wins-a.wins)[0]||null,record=all.map(({g,r})=>r[0]?{profileId:r[0].profileId,name:r[0].name,emoji:r[0].emoji,total:r[0].total,date:g.finishedAt}:null).filter(Boolean).sort((a,b)=>a.total-b.total)[0]||null;return{items,nextCursor:slice.at(-1)?.g.finishedAt||null,hasMore:filtered.length>limit,total:all.length,summary:{games:all.length,avgPlayers:all.length?Math.round(all.reduce((n,x)=>n+x.g.players.length,0)/all.length*10)/10:0,avgRounds:all.length?Math.round(all.reduce((n,x)=>n+x.g.rounds.length,0)/all.length*10)/10:0,topWinner,record}}},
    gameDetail: async gameId=>structuredClone(load().archive.find(g=>g.id===gameId)),
    addPlayer: async (name, emoji) => {
      const s = load();
      if (s.currentGame.players.length >= LIMIT) throw new Error("В игре уже 10 игроков");
      if (s.currentGame.rounds.length) throw new Error("Игроков можно менять только до первого раунда");
      let profile = s.knownPlayers.find(x => x.name.trim().toLowerCase() === name.trim().toLowerCase());
      if (!profile) { profile = { id: uid(), name, emoji }; s.knownPlayers.push(profile); }
      if (s.currentGame.players.some(x => x.profileId === profile.id)) throw new Error("Этот игрок уже участвует");
      s.currentGame.players.push({ id: uid(), profileId: profile.id, name: profile.name, emoji: profile.emoji, seat: s.currentGame.players.length + 1 });
      return save(s);
    },
    addExistingPlayer: async (profileId) => {
      const s = load();
      if (s.currentGame.rounds.length) throw new Error("Игроков можно менять только до первого раунда");
      if (s.currentGame.players.length >= LIMIT) throw new Error("В игре уже 10 игроков");
      const profile = s.knownPlayers.find(x => x.id === profileId);
      if (!profile) throw new Error("Игрок не найден");
      if (s.currentGame.players.some(x => x.profileId === profile.id)) throw new Error("Этот игрок уже участвует");
      s.currentGame.players.push({ id: uid(), profileId: profile.id, name: profile.name, emoji: profile.emoji, seat: s.currentGame.players.length + 1 });
      return save(s);
    },
    updatePlayerIcon: async (playerId, emoji) => {
      const s = load(); const player = s.currentGame.players.find(x => x.id === playerId);
      if (!player) throw new Error("Игрок не найден");
      const profile = s.knownPlayers.find(x => x.id === player.profileId); if (profile) profile.emoji = emoji;
      for (const item of [s.currentGame, ...s.archive].flatMap(g => g.players || [])) if (item.profileId === player.profileId) item.emoji = emoji;
      return save(s);
    },
    removePlayer: async (id) => {
      const s = load();
      if (s.currentGame.rounds.length) throw new Error("Игроков можно менять только до первого раунда");
      s.currentGame.players = s.currentGame.players.filter(p => p.id !== id).map((p, i) => ({ ...p, seat: i + 1 }));
      return save(s);
    },
    setDraftScore: async (playerId, score) => { const s=load();s.currentGame.draftScores[playerId]=score;save(s);return structuredClone(s.currentGame.draftScores); },
    clearDraftScore: async (playerId) => { const s=load();delete s.currentGame.draftScores[playerId];save(s);return structuredClone(s.currentGame.draftScores); },
    importGame: async (playedAt, profiles, rounds, mode="rounds") => { const s=load(),game={id:uid(),startedAt:playedAt,finishedAt:playedAt,scoreMode:mode,players:profiles.map((id,i)=>{const p=s.knownPlayers.find(x=>x.id===id);return{id:uid(),profileId:id,name:p.name,emoji:p.emoji,seat:i+1}}),rounds:[]};game.rounds=rounds.map((r,i)=>({id:uid(),number:i+1,createdAt:playedAt,scores:Object.fromEntries(game.players.map(x=>[x.id,r[x.profileId]]))}));s.archive.push(game);s.archive.sort((x,y)=>new Date(y.finishedAt)-new Date(x.finishedAt));return save(s); },
    finalizeRound: async token => { const s=load(),scores=s.currentGame.draftScores||{};if(s.currentGame.players.some(x=>!Object.prototype.hasOwnProperty.call(scores,x.id)))throw new Error("Сначала каждый игрок должен внести свои очки");s.currentGame.rounds.push({id:uid(),number:s.currentGame.rounds.length+1,createdAt:new Date().toISOString(),scores:{...scores}});s.currentGame.draftScores={};return save(s); },
    addRound: async (scores) => {
      const s = load();
      if (s.currentGame.players.length < 2) throw new Error("Добавьте минимум двух игроков");
      s.currentGame.rounds.push({ id: uid(), number: s.currentGame.rounds.length + 1, createdAt: new Date().toISOString(), scores });
      return save(s);
    },
    updateRound: async (roundId, scores) => {
      const s = load();
      const round = s.currentGame.rounds.find(r => r.id === roundId);
      if (!round) throw new Error("Раунд не найден");
      round.scores = scores;
      return save(s);
    },
    undoRound: async () => { const s = load(); s.currentGame.rounds.pop(); return save(s); },
    newGame: async (keepPlayers) => {
      const s = load();
      const old = s.currentGame;
      if (old.rounds.length) s.archive.unshift({ ...old, finishedAt: new Date().toISOString() });
      s.currentGame = {
        id: uid(), startedAt: new Date().toISOString(), rounds: [],
        players: keepPlayers ? old.players.map((p, i) => ({ ...p, id: uid(), seat: i + 1 })) : [], draftScores: {}
      };
      return save(s);
    }
  };
}

function rankingFor(game){return[...(game?.players||[])].map(p=>({...p,total:(game.rounds||[]).reduce((s,r)=>s+Number(r.scores?.[p.id]||0),0)})).sort((x,y)=>x.total-y.total||x.seat-y.seat)}
