function eloCalibrationText(info){const games=info?.games||0,remaining=Math.max(0,ELO_MIN_GAMES-games);return remaining===1?'Ещё 1 игра':`Ещё ${remaining} ${plural(remaining,'игра','игры','игр')}`}
function eloShort(info){return info?.official?`Эло ${info.rating}`:`Калибровка ${info?.games||0}/5`}
function eloCell(info){return info?.official?`<strong class="elo-number">${info.rating}</strong>`:`<span class="elo-calibration"><b>Калибровка</b><small>${info?.games||0} из 5 игр</small></span>`}
function eloChange(info){if(!info?.official)return`<span class="elo-change neutral">—</span>`;if(info.games===ELO_MIN_GAMES)return`<span class="elo-change opened">Открыт</span>`;const value=info.lastChange||0,sign=value>0?'+':'';return`<span class="elo-change ${value>0?'up':value<0?'down':'neutral'}">${sign}${value}</span>`}
function renderProfileElo(info){if(!info?.official)return`<div class="profile-elo-line calibration"><span><small>Рейтинг Эло</small><b>Калибровка</b></span><em>${info?.games||0} из 5 игр · ${eloCalibrationText(info).toLowerCase()}</em></div>`;const change=info.games===ELO_MIN_GAMES?'рейтинг открыт':`${info.lastChange>0?'+':''}${info.lastChange||0} после последней партии`;return`<div class="profile-elo-line"><span><small>Рейтинг Эло</small><b>${info.rating}</b></span><em class="${info.lastChange>0?'up':info.lastChange<0?'down':''}">${change}</em></div>`}
function profileEloChart(info){const rows=(info?.history||[]).filter(x=>x.beforeGames+1>=ELO_MIN_GAMES).slice(-12);if(!info?.official||rows.length<2)return"";const first=rows[0].beforeRating??rows[0].afterRating,last=rows.at(-1).afterRating,values=[first,...rows.map(x=>x.afterRating)],min=Math.min(...values),max=Math.max(...values),change=last-first,sign=change>0?"+":"";return`<section class="profile-elo-summary"><div><small>Эло за последние ${rows.length} официальных игр</small><b>${first} → ${last}</b><span>минимум ${min} · максимум ${max}</span></div><strong class="${change>0?"up":change<0?"down":"neutral"}">${sign}${change}</strong></section>`}
function renderEloHelp(){return`<div class="elo-help-wrap"><button type="button" class="elo-help" data-action="toggle-elo-help" aria-expanded="false" aria-label="Как считается рейтинг Эло">?</button><div class="elo-help-popover" role="tooltip"><b>Что показывает Эло</b><p>Рейтинг оценивает результат с учётом силы соперников. Стартовая скрытая отметка — 1000, число открывается после пяти партий.</p><b>Как считается партия</b><p>Ваш итог сравнивается отдельно с каждым соперником: меньший штрафной счёт — победа, одинаковый — ничья. Размер стола нормализуется, поэтому партия на девятерых не влияет в восемь раз сильнее дуэли.</p><b>Что влияет на изменение</b><ul><li>Победа над сильным приносит больше.</li><li>Победа над слабым приносит меньше.</li><li>Поражение от сильного отнимает немного.</li><li>Поражение от слабого отнимает больше.</li></ul><b>Что не влияет</b><p>Размер отрыва, количество раундов и переход через 66 очков. Эло всегда считается по всей истории и не меняется, если игрок пропустил партию.</p></div></div>`}

function formatDate(iso) {
  return new Intl.DateTimeFormat("ru-RU", { day: "numeric", month: "long", year: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso));
}
function cowMarks(score) {
  const n = Math.min(5, Math.max(1, Math.ceil(Number(score) / 15)));
  return `<span class="cow-marks" aria-hidden="true">${"●".repeat(n)}</span>`;
}
function showToast(message, kind = "ok") {
  clearTimeout(toastTimer);
  document.querySelector(".toast")?.remove();
  const el = document.createElement("div");
  el.className = `toast ${kind}`;
  el.setAttribute("role", "status");
  el.textContent = message;
  document.body.append(el);
  requestAnimationFrame(() => el.classList.add("show"));
  toastTimer = setTimeout(() => el.remove(), 3200);
}

async function mutate(action, success) {
  if (busy) { showToast("Предыдущее действие ещё сохраняется"); return false; }
  busy = true; render();
  try {
    const result = await action();
    state=mergeLive(result?.currentGame?result:await getLive());
    lastStateHash=JSON.stringify({...state,archive:[]});
    markSynchronized();modal=null;busy=false;render();scheduleSync(5000);
    if(success)showToast(success);
    return true;
  } catch (error) {
    busy=false;syncIssue=cloudMode;saveActiveSnapshot();render();scheduleSync(syncRetryDelay);
    showToast(error.message||"Изменение не сохранено — данные на экране не потеряны","error");
    return false;
  }
}

function historicalRoundHigh(game){let value=0,count=0;for(const archived of state.archive||[]){if(archived.id===game?.id||!hasRoundDetails(archived))continue;for(const round of archived.rounds||[])for(const score of Object.values(round.scores||{})){value=Math.max(value,Number(score)||0);count++}}return{value,count}}
