function refreshInsightDeck(){const current=document.querySelector('.daily-carousel');if(!current){render();return}const holder=document.createElement('div');holder.innerHTML=dailyCard(state.currentGame).trim();const next=holder.firstElementChild;if(!next)return;current.replaceWith(next);scheduleInsightAuto()}

/* ===== v8 redesign: game screen ===== */
const K8_CROWN='<svg class="k8-crown" viewBox="0 0 30 22" aria-hidden="true"><path fill="currentColor" d="M2 20 4 5l7 7 4-10 4 10 7-7 2 15z"/></svg>';
let k8StatsMemo={key:null,value:null};
function playerStatsIndex(){
  const archive=state?.archive||[],key=`${archive.length}:${archive[0]?.id||""}:${archive.at(-1)?.id||""}`;
  if(k8StatsMemo.key===key)return k8StatsMemo.value;
  const games=new Map(),wins=new Map();for(const g of archive){for(const p of g.players||[])if(p.profileId)games.set(p.profileId,(games.get(p.profileId)||0)+1);try{const r=rankingFor(g),best=r[0]?.total;for(const x of r)if(x.total===best&&x.profileId)wins.set(x.profileId,(wins.get(x.profileId)||0)+1)}catch{}}
  let elo=new Map();try{elo=eloRatings(archive)}catch{}
  let crown=null;for(const [id,e] of elo)if(e.official&&e.rank===1)crown=id;
  k8StatsMemo={key,value:{games,elo,wins,crown}};return k8StatsMemo.value;
}
function sortProfiles(list){
  const idx=playerStatsIndex(),g=p=>idx.games.get(p.id)||0,e=p=>{const x=idx.elo.get(p.id);return x?.official?x.rating:0};
  return[...list].sort((a,b)=>(playerSort==="elo"?(e(b)-e(a))||(g(b)-g(a)):(g(b)-g(a))||(e(b)-e(a)))||a.name.localeCompare(b.name,"ru"));
}
function seatMeta(p){const id=p.profileId||p.id,idx=playerStatsIndex(),g=idx.games.get(id)||0,e=idx.elo.get(id);if(e?.official)return`Эло ${e.rating}`;return g?`${g} ${plural(g,"партия","партии","партий")}`:"Новичок"}
function sortToggle(){return`<div class="k8-sort" role="group" aria-label="Сортировка игроков"><button type="button" class="${playerSort==="games"?"on":""}" data-action="player-sort" data-sort="games" aria-pressed="${playerSort==="games"}">Чаще играют</button><button type="button" class="${playerSort==="elo"?"on":""}" data-action="player-sort" data-sort="elo" aria-pressed="${playerSort==="elo"}">По Эло</button></div>`}
function k8Wins(id){return playerStatsIndex().wins.get(id)||0}
function k8EarnedFrames(id){const w=k8Wins(id);return K8_FRAMES.filter(f=>w>=f.wins)}
function k8BestFrame(id){return k8EarnedFrames(id).at(-1)?.id||"none"}
function k8ResolveFrame(id,chosen){if(chosen==="none")return"none";if(chosen&&k8EarnedFrames(id).some(f=>f.id===chosen))return chosen;return k8BestFrame(id)}
