function renderPagedArchive(){setTimeout(setupArchiveAutoLoad,0);const loading=!archiveFeed.loaded,total=archiveTotal(),monthFmt=new Intl.DateTimeFormat("ru-RU",{month:"long"}),cap=x=>x.charAt(0).toUpperCase()+x.slice(1);let lastMonth="";const rows=archiveFeed.items.map(g=>{const d=new Date(g.finishedAt||g.startedAt),month=`${cap(monthFmt.format(d))} ${d.getFullYear()}`,heading=month!==lastMonth?(lastMonth=month,`<div class="k8-arch-month">${month}</div>`):"",mode=g.scoreMode||"rounds",w=g.winner||{},wd=w.profileId||w.id?w:{...w,id:w.name};return`${heading}<button class="k8-arch-row" data-action="open-archive-game" data-id="${g.id}"><span class="k8-arch-date"><b>${d.getDate()}</b><small>${d.toLocaleDateString("ru-RU",{month:"short"}).replace(".","")}</small><em>${d.toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"})}</em></span>${k8Avatar(wd)}<span class="k8-arch-main"><b>${esc(w.name||"—")}</b><small>${g.playerCount} ${plural(g.playerCount,"игрок","игрока","игроков")} · ${mode==="totals"?`<em class="k8-arch-tag">только итоги</em>`:`${g.roundCount} ${plural(g.roundCount,"раунд","раунда","раундов")}`}</small></span><strong>${w.total??"—"}<small>${w.total!=null?plural(w.total,"очко","очка","очков"):""}</small></strong><i aria-hidden="true">›</i></button>`}).join("");return`<section class="k8 k8-archive"><div class="k8-hero k8-arch-hero"><div class="k8-hero-top"><span class="k8-eyebrow">Архив · ${total} ${plural(total,"партия","партии","партий")}</span><button class="k8-arch-add" data-action="open-import">＋ Прошлая партия</button></div><h1>Прошлые игры</h1><p>Все завершённые партии стола. Нажмите на партию, чтобы открыть счёт, ход игры и номинации.</p></div>${archiveFilterForm()}${loading?`<div class="archive-loading-cards k8-arch-loading"><i></i><i></i><i></i></div>`:archiveFeed.total===0?(archiveFiltersActive()?`<div class="k8-arch-empty"><b>Ничего не найдено</b><span>Попробуйте изменить условия или очистить фильтры.</span><button class="k8-arch-reset" type="button" data-action="reset-archive-filters">Сбросить фильтры</button></div>`:`<div class="k8-arch-empty"><b>Архив ещё пуст</b><span>Завершённые партии появятся здесь.</span></div>`):`<div class="k8-arch-results"><div class="k8-head"><h2>Результаты</h2><span>${archiveFiltersActive()?`Найдено ${archiveFeed.total} · `:""}показано ${archiveFeed.items.length} из ${archiveFeed.total}</span></div><div class="k8-arch-list">${rows}</div>${archiveFeed.hasMore?`<span class="archive-auto-sentinel" aria-hidden="true"></span><button class="k8-arch-more" data-action="archive-load-more" ${archiveFeed.loading?"disabled":""}>${archiveFeed.loading?"Загружаем…":"Показать ещё"}</button>`:""}</div>`}</section>`}
