    return shell(`<form id="edit-profile-form" class="profile-identity-form k8-prof"><span class="eyebrow">Профиль игрока</span><div ${profileAttrs(look,"identity-preview k8-prof-preview")}>${k8Avatar({id:profile.id,emoji:selectedEmoji,accent:selectedAccent,pattern:selectedPattern},"k8-prof-av",true,previewFrame)}<div class="k8-prof-id"><label class="k8-prof-label" for="k8-prof-name">Имя</label><input id="k8-prof-name" class="k8-prof-name" name="name" value="${esc(profileNameDraft??profile.name)}" maxlength="24" autocomplete="off" required><small>${selectedAward?`🏅 ${esc(selectedAward)}`:"Без титула"}</small></div>${(luckyDraft??extras.luckyCard)?k8Card(luckyDraft??extras.luckyCard,"k8-card-prev"):""}</div><div class="k8-ptabs" role="tablist" aria-label="Разделы оформления">${tabs.map(([id,label])=>`<button type="button" role="tab" aria-selected="${profileTab===id}" class="${profileTab===id?"on":""}" data-action="profile-tab" data-ptab="${id}">${label}</button>`).join("")}</div><div class="k8-prof-body">${body}</div><div class="k8-prof-save"><button class="button primary large full" type="submit">${icon("save")} Сохранить</button></div></form>`,"k8-prof-modal");
