function plural(n, one, few, many) {
  const mod10 = n % 10, mod100 = n % 100;
  return mod10 === 1 && mod100 !== 11 ? one : mod10 >= 2 && mod10 <= 4 && !(mod100 >= 12 && mod100 <= 14) ? few : many;
}

function awardPlayers(item){return item?.players?.length?item.players:item?.player?[item.player]:[]}
function awardPlayersLabel(item){return awardPlayers(item).map(player=>`${player.emoji} ${player.name}`).join(", ")}
function funAwards(game){const ranks=ranking(game),out=[];if(!ranks.length)return out;const winner=ranks[0],last=ranks.at(-1);out.push({title:"Не сегодня, коровы",player:winner,desc:"Лучший итог партии"});if(last.id!==winner.id)out.push({title:"Пылесос коров",player:last,desc:"Самый большой итог"});let biggest={player:null,value:-1},zeros=[];for(const p of game.players){let z=0;for(const r of game.rounds){const v=Number(r.scores[p.id]??0);if(v===0)z++;if(v>biggest.value)biggest={player:p,value:v}}zeros.push({p,v:z})}if(biggest.player)out.push({title:"Главный животновод",player:biggest.player,desc:`Самый крупный раунд: +${biggest.value}`});const zeroMax=Math.max(0,...zeros.map(item=>item.v));if(zeroMax){const players=zeros.filter(item=>item.v===zeroMax).map(item=>item.p);out.push({title:"Мимо проходило стадо",player:players[0],players,desc:`Нулевых раундов у каждого: ${zeroMax}`})}const closest=[...ranks].sort((a,b)=>Math.abs(a.total-66)-Math.abs(b.total-66))[0];out.push({title:"На грани фола",player:closest,desc:`Ближе всех к 66: ${closest.total}`});if(ranks[1]&&ranks[1].total-winner.total<=3)out.push({title:"Фотофиниш",player:winner,desc:`Победа с разницей ${ranks[1].total-winner.total}`});return out.slice(0,6)}

function canvasRoundedRect(ctx,x,y,w,h,r,fill,stroke=null,lineWidth=1){const rr=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+rr,y);ctx.arcTo(x+w,y,x+w,y+h,rr);ctx.arcTo(x+w,y+h,x,y+h,rr);ctx.arcTo(x,y+h,x,y,rr);ctx.arcTo(x,y,x+w,y,rr);ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lineWidth;ctx.stroke()}}
function canvasWrappedText(ctx,text,x,y,maxWidth,lineHeight,maxLines=3){const words=String(text).split(/\s+/),lines=[];let line='';for(const word of words){const test=line?`${line} ${word}`:word;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=word;if(lines.length===maxLines-1)break}else line=test}if(line&&lines.length<maxLines)lines.push(line);if(lines.length===maxLines&&words.join(' ').length>lines.join(' ').length)lines[maxLines-1]=lines[maxLines-1].replace(/[.,;:!?]?$/,'…');lines.forEach((value,i)=>ctx.fillText(value,x,y+i*lineHeight));return y+lines.length*lineHeight}
