function createAwardsCanvas(game){const{canvas,ctx}=resultCanvasBase(game,'Номинации','Герои этой партии',3),awards=funAwards(game).slice(0,6);canvasRoundedRect(ctx,64,320,952,916,24,'#fffaf0','#201e1b',4);ctx.fillStyle='#765d18';ctx.font='900 17px Arial';ctx.fillText('ШУТОЧНОЕ НАГРАЖДЕНИЕ',108,370);const icons=['🏅','🎖️','🥇','🐮','🎯','✨'],colW=430,rowH=244;awards.forEach((item,index)=>{const col=index%2,row=Math.floor(index/2),x=94+col*452,y=402+row*rowH;canvasRoundedRect(ctx,x,y,colW,224,18,index%2?'#fff3c7':'#ffffff','#d0bc78',2);ctx.font='43px Arial';ctx.fillText(icons[index%icons.length],x+25,y+60);ctx.fillStyle='#765d18';ctx.font='900 14px Arial';ctx.fillText('НОМИНАЦИЯ',x+86,y+37);ctx.fillStyle='#201e1b';canvasFittedText(ctx,item.title,x+86,y+72,315,24,18,900);ctx.font='800 22px Arial';canvasWrappedText(ctx,awardPlayersLabel(item),x+28,y+122,colW-56,27,2);ctx.fillStyle='#625b4c';ctx.font='18px Arial';canvasWrappedText(ctx,item.desc,x+28,y+181,colW-56,23,2)});return canvas}
