async function copyResultCard(game,kind='summary'){const story=kind==='story',awards=kind==='awards',canvas=story?createStoryCanvas(game):awards?createAwardsCanvas(game):createScoreCanvas(game),blob=await canvasBlob(canvas),label=story?'Ход игры':awards?'Номинации':'Итоговый счёт';if(navigator.clipboard?.write&&window.ClipboardItem){try{await navigator.clipboard.write([new ClipboardItem({'image/png':blob})]);showToast(`${label} скопирован — вставьте изображение в мессенджер`);return}catch(error){if(error?.name==='NotAllowedError'){showToast('Chrome запретил копирование. Разрешите сайту доступ к буферу обмена и повторите.','error');return}}showToast('Браузер не поддерживает копирование изображений. Используйте актуальный Chrome или Safari.','error')}}

async function finishCurrentGame(keepPlayers) {
  if (busy || !state.currentGame.rounds.length) return;
  const finished = structuredClone(state.currentGame);
  busy = true; render();
  try {
    const result = await api.newGame(keepPlayers);
    state=mergeLive(result?.currentGame?result:await getLive());
    lastStateHash=JSON.stringify({...state,archive:[]});
    if(cloudMode){invalidateHistory();setTimeout(()=>ensureHistory(true).catch(()=>{}),0)}else{state.archiveCount=state.archive.length;statsMemo={key:null,value:null}}
    celebrationGame = finished;
    winnerTab = "summary";
    modal = "winner";
    busy = false; render();
  } catch (error) {
    busy = false; render(); showToast(error.message || "Не удалось завершить игру", "error");
  }
}

